import re, glob

def check(fname):
    with open(fname, encoding="utf-8") as f:
        raw = f.read()
    # join line-continuations
    raw = raw.replace(" _\r\n", " ").replace(" _\n", " ")
    lines = raw.split("\n")
    stack = []
    problems = []
    for lineno, line in enumerate(lines, 1):
        code = line.split("'", 1)[0]  # strip comments (naive, ignores strings with ')
        stripped = code.strip()
        if not stripped:
            continue
        # block openers
        if re.match(r'^(Public |Private )?(Function|Sub)\b', stripped):
            stack.append(('Function/Sub', lineno, stripped[:60]))
        elif stripped.startswith('End Function') or stripped.startswith('End Sub'):
            if not stack or stack[-1][0] != 'Function/Sub':
                problems.append((lineno, "unexpected End Function/Sub"))
            else:
                stack.pop()
        elif re.match(r'^If\b.*\bThen\s*$', stripped) and not re.search(r'\bEnd If\b', stripped):
            stack.append(('If', lineno, stripped[:60]))
        elif stripped == 'End If':
            if not stack or stack[-1][0] != 'If':
                problems.append((lineno, "unexpected End If, top is %s" % (stack[-1] if stack else None)))
            else:
                stack.pop()
        elif re.match(r'^For\b', stripped):
            stack.append(('For', lineno, stripped[:60]))
        elif re.match(r'^Next\b', stripped):
            if not stack or stack[-1][0] != 'For':
                problems.append((lineno, "unexpected Next, top is %s" % (stack[-1] if stack else None)))
            else:
                stack.pop()
        elif re.match(r'^Do\b', stripped):
            stack.append(('Do', lineno, stripped[:60]))
        elif re.match(r'^Loop\b', stripped):
            if not stack or stack[-1][0] != 'Do':
                problems.append((lineno, "unexpected Loop"))
            else:
                stack.pop()
        elif re.match(r'^With\b', stripped):
            stack.append(('With', lineno, stripped[:60]))
        elif stripped == 'End With':
            if not stack or stack[-1][0] != 'With':
                problems.append((lineno, "unexpected End With"))
            else:
                stack.pop()
        elif re.match(r'^Select Case\b', stripped):
            stack.append(('Select', lineno, stripped[:60]))
        elif stripped == 'End Select':
            if not stack or stack[-1][0] != 'Select':
                problems.append((lineno, "unexpected End Select"))
            else:
                stack.pop()

    print("=== %s ===" % fname)
    if problems:
        for p in problems:
            print("  PROBLEM:", p)
    if stack:
        print("  UNCLOSED at EOF:", stack)
    if not problems and not stack:
        print("  OK")

for f in ["Helpers.bas","FilterFileA.bas","FilterFileB.bas","DeduplicateEncounters.bas","BuildOutput.bas","MainMacro.bas","FilePickerForm.bas"]:
    check(f)
